/**
 * 朋友圈（微信 Moments）专属：彩色相机光圈（aperture）。
 * 依照官方"朋友圈"标识重建——多片彩色叶片呈风车状旋绕、中心留小孔，
 * 形成相机光圈观感。多色，不随 currentColor 变化。
 */
const MOMENTS_COLORS = [
  "#FF4D4F", // 红
  "#FF8A00", // 橙
  "#FFC300", // 黄
  "#52C41A", // 绿
  "#13C2C2", // 青
  "#1890FF", // 蓝
  "#2F54EB", // 靛
  "#9254DE"  // 紫
];

/**
 * 计算光圈叶片路径：圆心 (12,12)，外径 R，中心孔半径 rh，swirl 控制风车旋角。
 * 每片叶 = 一段外圆弧 + 收向中心孔的两条直边，相邻叶片共享外缘端点、
 * 内顶点绕小圆错开，从而形成风车/快门式的中心多边孔。
 */
function buildMomentsBlades(): string[] {
  const cx = 12;
  const cy = 12;
  const R = 11;
  const rh = 2.7;
  const swirl = 0.62;
  const n = MOMENTS_COLORS.length;
  const step = (Math.PI * 2) / n;
  const start = -Math.PI / 2;
  const pt = (r: number, a: number) =>
    `${(cx + r * Math.cos(a)).toFixed(2)} ${(cy + r * Math.sin(a)).toFixed(2)}`;
  const blades: string[] = [];
  for (let k = 0; k < n; k++) {
    const a0 = start + k * step;
    const a1 = a0 + step;
    blades.push(`M ${pt(R, a0)} A ${R} ${R} 0 0 1 ${pt(R, a1)} L ${pt(rh, a1 + swirl)} Z`);
  }
  return blades;
}

const MOMENTS_BLADES = buildMomentsBlades();

function MomentsGlyph() {
  return (
    <>
      {MOMENTS_BLADES.map((d, i) => (
        <path key={i} d={d} fill={MOMENTS_COLORS[i]} />
      ))}
    </>
  );
}

const brandColor: Record<PlatformId, string> = {
  wechat: "#07C160",
  xiaohongshu: "#FF2442",
  zhihu: "#0066FF",
  moments: "#07C160",
  x: "#0F1419",
  linkedin: "#0A66C2",
  reddit: "#FF4500",
  "product-hunt": "#DA552F",
  threads: "#0F1419",
  "hacker-news": "#FF6600",
  "indie-hackers": "#0E2439",
  "medium-substack": "#FF6719",
  instagram: "#E4405F",
  facebook: "#1877F2"
};

/**
 * 纯品牌字形（无背景方块）。
 * 单色平台 fill 跟随 currentColor；朋友圈渲染专属彩色光圈（保持品牌彩色）。
 * 用于任意尺寸 / 配色场景：首页平台网格、hero 卡片、规则示意等。
 */
export function PlatformGlyph({ platform, className = "" }: { platform: PlatformId; className?: string }) {
  if (platform === "moments") {
    return (
      <svg viewBox="0 0 24 24" className={className} aria-hidden="true">
        <MomentsGlyph />
      </svg>
    );
  }
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" className={className} aria-hidden="true">
      <path d={glyphPath[platform]} />
    </svg>
  );
}

export function PlatformBrandIcon({ platform, selected = false, className = "" }: PlatformBrandIconProps) {
  const color = brandColor[platform];
  const softColor = `${brandColor[platform]}${selected ? "24" : "18"}`;

  return (
    <svg viewBox="0 0 40 40" aria-hidden="true" className={className}>
      <rect width="40" height="40" rx="12" fill={softColor} />
      <g transform="translate(8 8)">
        {platform === "moments" ? (
          <MomentsGlyph />
        ) : (
          <path d={glyphPath[platform]} fill={color} />
        )}
      </g>
    </svg>
  );
}
